-- Sincronización puntual de ORIGEN y NEXUM desde el catálogo local (19-10-2026).
-- Es idempotente y no cambia eventos ya existentes. Las fichas indican que son ejemplos ficticios.
BEGIN;

INSERT INTO connectify.events ("id", "title", "description", "category_id", "event_date", "location", "city", "organizer_name", "organizer_email", "price", "capacity", "tickets_sold", "image_url", "design_template", "status", "created_at", "updated_at" , "design_enabled", "featured")
SELECT r."id", r."title", r."description", r."category_id", r."event_date", r."location", r."city", r."organizer_name", r."organizer_email", r."price", r."capacity", r."tickets_sold", r."image_url", r."design_template", r."status", r."created_at", r."updated_at", false, false
FROM jsonb_populate_recordset(NULL::connectify.events, '[{"id":24,"title":"ORIGEN · Mesa del Pacífico","description":"Una experiencia gastronómica que conecta huerto, costa y mesa. Estaciones de cocina abierta, mercado de productores y una sobremesa musical reúnen ingredientes de temporada y técnicas contemporáneas. Apertura a las 11:30, actividades de 12:00 a 20:00. Las degustaciones incluidas dependen del pase; opciones vegetarianas previa coordinación con soporte. Menores acompañados por un adulto. Propuesta ficticia de demostración: precios, recinto y programa son ilustrativos.","category_id":3,"event_date":"2027-03-13 12:00:00.000000","location":"Patio Mar de Tierra · espacio conceptual","city":"Lima","organizer_name":"Origen Taller","organizer_email":"org@connectify.com","price":35,"capacity":552,"tickets_sold":0,"image_url":"/images/showcase/origen-cover.png","design_template":"IMMERSIVE","status":"PUBLISHED","created_at":"2026-10-16 15:58:35.000000","updated_at":"2026-10-18 21:41:46.000000"},{"id":25,"title":"NEXUM · Ideas que conectan","description":"Un foro de innovación aplicada para profesionales, estudiantes y equipos. Conferencias, laboratorios de prototipado y espacios de conversación conectan diseño, tecnología y negocio. Acreditación desde las 08:00; programa principal de 09:00 a 18:30. Los laboratorios requieren el pase indicado y tienen aforo definido. Certificado digital de participación, sin acreditación académica. Propuesta ficticia de demostración: ponencias, sede y precios ilustrativos.","category_id":2,"event_date":"2027-04-09 09:00:00.000000","location":"Foro Horizonte · espacio conceptual","city":"Lima","organizer_name":"Nexum Lab","organizer_email":"org@connectify.com","price":45,"capacity":590,"tickets_sold":0,"image_url":"/images/showcase/nexum-cover.png","design_template":"TICKET_PANEL","status":"PUBLISHED","created_at":"2026-10-16 15:58:35.000000","updated_at":"2026-10-18 21:42:32.000000"}]'::jsonb) AS r
WHERE NOT EXISTS (SELECT 1 FROM connectify.events existing WHERE existing.id = r.id OR (existing.title = r.title AND existing.organizer_email = r.organizer_email));

INSERT INTO connectify.event_presentation_settings ("event_id", "primary_color", "accent_color", "highlight_text", "cover_image_url", "thumbnail_image_url", "background_image_url", "stage_image_url", "organizer_brand_name", "organizer_logo_url", "sponsor_logos_text", "cover_focus", "content_focus", "info_position", "show_gallery", "show_organizer", "show_agenda", "agenda_text", "show_benefits", "benefits_text", "show_sponsors", "sponsors_text", "show_media", "youtube_url", "spotify_url", "show_stage_map", "stage_text", "show_sessions", "session_text", "updated_at")
SELECT r."event_id", r."primary_color", r."accent_color", r."highlight_text", r."cover_image_url", r."thumbnail_image_url", r."background_image_url", r."stage_image_url", r."organizer_brand_name", r."organizer_logo_url", r."sponsor_logos_text", r."cover_focus", r."content_focus", r."info_position", r."show_gallery", r."show_organizer", r."show_agenda", r."agenda_text", r."show_benefits", r."benefits_text", r."show_sponsors", r."sponsors_text", r."show_media", r."youtube_url", r."spotify_url", r."show_stage_map", r."stage_text", r."show_sessions", r."session_text", r."updated_at"
FROM jsonb_populate_recordset(NULL::connectify.event_presentation_settings, '[{"event_id":24,"primary_color":"#38523F","accent_color":"#D49A60","highlight_text":"DEL TERRITORIO A LA MESA · Cocina abierta, oficios y encuentro","cover_image_url":"/images/showcase/origen-cover.png","thumbnail_image_url":"/images/showcase/origen-cover.png","background_image_url":"/images/showcase/origen-cover.png","stage_image_url":"/images/showcase/origen-stage.svg","organizer_brand_name":"Origen Taller","organizer_logo_url":"/images/showcase/organizer-mark.svg","sponsor_logos_text":"/images/showcase/partner-onda.svg\n/images/showcase/partner-raiz.svg\n/images/showcase/partner-nodo.svg","cover_focus":"CENTER","content_focus":"INFORMATION","info_position":"STANDARD","show_gallery":true,"show_organizer":true,"show_agenda":true,"agenda_text":"11:30 · Bienvenida y recorrido de productores\n12:00 · Apertura del mercado y cocina de costa\n13:30 · Taller de ingredientes de temporada\n15:00 · Mesa de autor: servicio guiado\n17:00 · Conversación de productores y técnicas\n18:30 · Sobremesa acústica · cierre 20:00","show_benefits":true,"benefits_text":"Acceso al mercado, demostraciones abiertas y música acústica con todos los pases.\nPreferencial: dos degustaciones; VIP: cuatro degustaciones y taller.\nPlatinum: menú guiado de cinco pasos con bebida sin alcohol.\nPalco: mesa individual junto al escenario de cocina.\nMeet & Greet: conversación guiada con el equipo de cocina.\nInformar alergias; no se garantiza ausencia de trazas.","show_sponsors":true,"sponsors_text":"Aliados ficticios de esta demostración: ONDA · RAÍZ · NODO. No representan patrocinios reales.","show_media":true,"youtube_url":"https://www.youtube.com/watch?v=aqz-KE-bpKQ","spotify_url":"https://open.spotify.com/playlist/37i9dQZF1DX4sWSpwq3LiO","show_stage_map":true,"stage_text":"Cocina abierta al norte; Platinum frente al pase; VIP al este; Preferencial junto al huerto; General en mercado central; Palco con mesas junto a cocina; Meet & Greet en Taller del Chef. 300 + 120 + 60 + 36 + 24 + 12 = 552 plazas. Circulación accesible, agua, baños y asistencia señalizados. Plano conceptual.\nMedia de referencia: cortometraje Big Buck Bunny y playlist Peaceful Piano; no son material promocional de este evento.","show_sessions":true,"session_text":"13 marzo 2027 · Mercado y cocina abierta · 12:00–20:00\n13 marzo 2027 · Mesa de autor · 15:00 (Platinum)\n13 marzo 2027 · Taller del Chef · 16:30 (Meet & Greet)","updated_at":"2026-10-16 15:58:35.000000"},{"event_id":25,"primary_color":"#123A4A","accent_color":"#46C4BD","highlight_text":"IDEAS CLARAS. CONEXIONES REALES. · Foro de innovación aplicada","cover_image_url":"/images/showcase/nexum-cover.png","thumbnail_image_url":"/images/showcase/nexum-cover.png","background_image_url":"/images/showcase/nexum-cover.png","stage_image_url":"/images/showcase/nexum-stage.svg","organizer_brand_name":"Nexum Lab","organizer_logo_url":"/images/showcase/organizer-mark.svg","sponsor_logos_text":"/images/showcase/partner-onda.svg\n/images/showcase/partner-raiz.svg\n/images/showcase/partner-nodo.svg","cover_focus":"CENTER","content_focus":"BALANCED","info_position":"SIDEBAR","show_gallery":true,"show_organizer":true,"show_agenda":true,"agenda_text":"08:00 · Acreditación y café de bienvenida\n09:00 · Apertura: diseñar con intención\n10:30 · Panel: tecnología aplicada a servicios\n12:00 · Laboratorios de prototipado por nivel de pase\n14:30 · Casos y demostraciones en escenario principal\n16:00 · Rondas de conversación\n18:00 · Cierre y conclusiones · salida 18:30","show_benefits":true,"benefits_text":"Conferencias, expo de proyectos y certificado digital con todos los pases.\nEstudiante: mismo acceso General con identificación vigente.\nPreferencial: primeras filas centrales y material del foro.\nVIP: laboratorio de prototipado y lounge.\nCorporativo: pase individual para equipos, laboratorio y mesa de trabajo.\nMeet & Greet: sesión de preguntas con facilitadores al final del foro.","show_sponsors":true,"sponsors_text":"Aliados ficticios de esta demostración: ONDA · RAÍZ · NODO. No representan patrocinios reales.","show_media":true,"youtube_url":"https://www.youtube.com/watch?v=aqz-KE-bpKQ","spotify_url":"https://open.spotify.com/playlist/37i9dQZF1DX4sWSpwq3LiO","show_stage_map":true,"stage_text":"Auditorio principal al norte; General al centro y atrás; Estudiante al oeste; Preferencial en filas centrales delanteras; VIP al este; Corporativo en laboratorio B; Meet & Greet en sala de encuentro. 260 + 100 + 100 + 50 + 60 + 20 = 590 plazas. Ruta accesible sin escalones, acreditación y salidas señalizadas. Sectores conceptuales sin butaca asignada.\nMedia de referencia: cortometraje Big Buck Bunny y playlist Peaceful Piano; no son material promocional de este evento.","show_sessions":true,"session_text":"09 abril 2027 · Auditorio principal · 09:00–18:30\n09 abril 2027 · Laboratorio A · 12:00 (VIP y Meet & Greet)\n09 abril 2027 · Laboratorio B · 12:00 (Corporativo)","updated_at":"2026-10-16 15:58:35.000000"}]'::jsonb) AS r
JOIN connectify.events e ON e.id = r.event_id AND e.title IN ('ORIGEN · Mesa del Pacífico', 'NEXUM · Ideas que conectan')
WHERE NOT EXISTS (SELECT 1 FROM connectify.event_presentation_settings existing WHERE existing.event_id = r.event_id);

INSERT INTO connectify.ticket_types ("event_id", "name", "price", "quantity_available", "quantity_sold", "description", "sales_start", "sales_end", "active")
SELECT r."event_id", r."name", r."price", r."quantity_available", r."quantity_sold", r."description", r."sales_start", r."sales_end", r."active"
FROM jsonb_populate_recordset(NULL::connectify.ticket_types, '[{"event_id":24,"name":"General","price":35,"quantity_available":300,"quantity_sold":0,"description":"Recorrido del mercado, cocina en vivo y sobremesa musical. Consumos no incluidos.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-03-13 12:00:00.000000","active":true},{"event_id":24,"name":"Preferencial","price":65,"quantity_available":120,"quantity_sold":0,"description":"Acceso General más dos degustaciones de estaciones seleccionadas.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-03-13 12:00:00.000000","active":true},{"event_id":24,"name":"VIP","price":115,"quantity_available":60,"quantity_sold":0,"description":"Cuatro degustaciones, taller de ingredientes y acceso preferente.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-03-13 12:00:00.000000","active":true},{"event_id":24,"name":"Platinum","price":185,"quantity_available":36,"quantity_sold":0,"description":"Menú de cinco pasos a las 15:00 y una bebida sin alcohol.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-03-13 12:00:00.000000","active":true},{"event_id":24,"name":"Palco","price":230,"quantity_available":24,"quantity_sold":0,"description":"Plaza individual en mesa junto a cocina, menú de cinco pasos y vista al pase.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-03-13 12:00:00.000000","active":true},{"event_id":24,"name":"Meet & Greet","price":275,"quantity_available":12,"quantity_sold":0,"description":"Experiencia Platinum y conversación guiada de 30 minutos con el equipo de cocina.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-03-13 12:00:00.000000","active":true},{"event_id":25,"name":"General","price":90,"quantity_available":260,"quantity_sold":0,"description":"Conferencias, expo de proyectos y certificado digital de participación.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-04-09 09:00:00.000000","active":true},{"event_id":25,"name":"Estudiante","price":45,"quantity_available":100,"quantity_sold":0,"description":"Acceso General presentando identificación estudiantil vigente.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-04-09 09:00:00.000000","active":true},{"event_id":25,"name":"Preferencial","price":130,"quantity_available":100,"quantity_sold":0,"description":"Primeras filas centrales y material digital del foro. No incluye laboratorio.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-04-09 09:00:00.000000","active":true},{"event_id":25,"name":"VIP","price":210,"quantity_available":50,"quantity_sold":0,"description":"Acceso Preferencial, laboratorio A y lounge de conversación.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-04-09 09:00:00.000000","active":true},{"event_id":25,"name":"Corporativo","price":250,"quantity_available":60,"quantity_sold":0,"description":"Pase individual de equipo: laboratorio B, material y mesa de trabajo.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-04-09 09:00:00.000000","active":true},{"event_id":25,"name":"Meet & Greet","price":320,"quantity_available":20,"quantity_sold":0,"description":"Acceso VIP y ronda de preguntas de 30 minutos con facilitadores.","sales_start":"2026-10-16 15:58:35.000000","sales_end":"2027-04-09 09:00:00.000000","active":true}]'::jsonb) AS r
JOIN connectify.events e ON e.id = r.event_id AND e.title IN ('ORIGEN · Mesa del Pacífico', 'NEXUM · Ideas que conectan')
WHERE NOT EXISTS (SELECT 1 FROM connectify.ticket_types existing WHERE existing.event_id = r.event_id AND existing.name = r.name);

-- Son fichas ficticias: conservar las variantes para edición, sin ofrecerlas a la venta.
UPDATE connectify.ticket_types SET active = false WHERE event_id IN (24, 25);
SELECT setval(pg_get_serial_sequence('connectify.events', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM connectify.events), (SELECT last_value FROM connectify.events_id_seq)), true);
COMMIT;
